tool_input.command:
node --test test/ 2>&1 | tail -8; mkdir -p /tmp/api-review && cat > /tmp/api-review/probe.mjs <<'EOF'
const root = process.argv[2];
const { handle } = await import(`${root}/src/api.js`);
const { reset, queryLog } = await import(`${root}/src/db.js`);
const { dueReminders } = await import(`${root}/src/scheduler.js`);

// 1. End-to-end: IST user, 09:00 local = 03:30Z
reset();
const r = handle({ method: 'POST', path: '/reminders', body: { userId: 'u1', text: 'x', at: '2026-03-01T09:00', tzOffsetMin: 330 } }).body;
console.log('stored due_ms', new Date(r.due_ms).toISOString());
for (const t of ['2026-02-28T22:00:00Z', '2026-03-01T03:30:00Z']) console.log('  due at', t, '->', dueReminders([r], Date.parse(t)).length);

// 2. Bad `at` formats
for (const at of ['2026-03-01T09:00:00', '2026-03-01', 'tomorrow', '2026-03-01T09:00Z']) {
  reset();
  const res = handle({ method: 'POST', path: '/reminders', body: { userId: 'u1', text: 'x', at } });
  console.log('at', JSON.stringify(at), '->', res.status, 'due_ms', res.body.due_ms);
}
// non-numeric offset
reset();
console.log('tz "abc" ->', handle({ method: 'POST', path: '/reminders', body: { userId: 'u1', text: 'x', at: '2026-03-01T09:00', tzOffsetMin: 'abc' } }).body.due_ms);

// 3. Search SQL built by concatenation
reset();
handle({ method: 'POST', path: '/reminders', body: { userId: 'u1', text: 'secret', at: '2026-03-01T09:00' } });
handle({ method: 'GET', path: '/reminders/search', query: { userId: "u2", q: "x" } });
handle({ method: 'GET', path: '/reminders/search', query: { userId: "u2' OR '1'='1", q: "" } });
console.log('SQL:', queryLog.at(-1).sql);
try { handle({ method: 'GET', path: '/reminders/search', query: { userId: "u1", q: "a' OR 'b" } }); console.log('no throw'); } catch (e) { console.log('search throws:', e.message); }

// 4. missing query object
try { handle({ method: 'GET', path: '/reminders' }); } catch (e) { console.log('list w/o query throws:', e.message); }
EOF
node /tmp/api-review/probe.mjs "$PWD"

tool_input.content:
const root = process.argv[2];
const { handle } = await import(`${root}/src/api.js`);
const { reset, queryLog } = await import(`${root}/src/db.js`);
const { dueReminders } = await import(`${root}/src/scheduler.js`);

// 1. End-to-end: IST user, 09:00 local = 03:30Z
reset();
const r = handle({ method: 'POST', path: '/reminders', body: { userId: 'u1', text: 'x', at: '2026-03-01T09:00', tzOffsetMin: 330 } }).body;
console.log('stored due_ms', new Date(r.due_ms).toISOString());
for (const t of ['2026-02-28T22:00:00Z', '2026-03-01T03:30:00Z']) console.log('  due at', t, '->', dueReminders([r], Date.parse(t)).length);

// 2. Bad `at` formats
for (const at of ['2026-03-01T09:00:00', '2026-03-01', 'tomorrow', '2026-03-01T09:00Z']) {
  reset();
  const res = handle({ method: 'POST', path: '/reminders', body: { userId: 'u1', text: 'x', at } });
  console.log('at', JSON.stringify(at), '->', res.status, 'due_ms', res.body.due_ms);
}
reset();
console.log('tz "abc" ->', handle({ method: 'POST', path: '/reminders', body: { userId: 'u1', text: 'x', at: '2026-03-01T09:00', tzOffsetMin: 'abc' } }).body.due_ms);

// 3. Search SQL built by concatenation
reset();
handle({ method: 'POST', path: '/reminders', body: { userId: 'u1', text: 'secret', at: '2026-03-01T09:00' } });
handle({ method: 'GET', path: '/reminders/search', query: { userId: "u2' OR '1'='1", q: '' } });
console.log('SQL:', queryLog.at(-1).sql);
try { handle({ method: 'GET', path: '/reminders/search', query: { userId: 'u1' } }); console.log('SQL:', queryLog.at(-1).sql); } catch (e) { console.log('throws:', e.message); }

// 4. missing query object
try { handle({ method: 'GET', path: '/reminders' }); } catch (e) { console.log('list w/o query throws:', e.message); }
